from solution import eulerian_num


def test_issue_example_3_1():
    """Example: eulerian_num(3, 1) == 4."""
    assert eulerian_num(3, 1) == 4  # (3-1)*1 + (1+1)*1 = 2+2 = 4


def test_issue_n1_m0():
    """Eulerian number a(1, 0) is 1."""
    assert eulerian_num(1, 0) == 1  # only [1] has 0 ascents = 1


def test_issue_n2_m0():
    """Eulerian number a(2, 0) is 1."""
    assert eulerian_num(2, 0) == 1  # only [2,1] has 0 ascents = 1


def test_issue_n2_m1():
    """Eulerian number a(2, 1) is 1."""
    assert eulerian_num(2, 1) == 1  # only [1,2] has 1 ascent = 1


def test_issue_n3_m0():
    """Eulerian number a(3, 0) is 1."""
    assert eulerian_num(3, 0) == 1  # only [3,2,1] has 0 ascents = 1


def test_issue_n3_m2():
    """Eulerian number a(3, 2) is 1."""
    assert eulerian_num(3, 2) == 1  # only [1,2,3] has 2 ascents = 1


def test_issue_n4_m1():
    """Eulerian number a(4, 1) is 11."""
    assert eulerian_num(4, 1) == 11  # (4-1)*1 + 2*4 = 3+8 = 11


def test_issue_n4_m2():
    """Eulerian number a(4, 2) is 11."""
    assert eulerian_num(4, 2) == 11  # (4-2)*4 + 3*1 = 8+3 = 11


def test_issue_n5_m2():
    """Eulerian number a(5, 2) is 66."""
    assert eulerian_num(5, 2) == 66  # 3*11 + 3*11 = 33+33 = 66


def test_issue_boundary_just_above():
    """Eulerian number with m just above range (3, 3) is 0."""
    assert eulerian_num(3, 3) == 0  # m=3 >= n=3 so no permutation = 0


def test_contract_row_sum_factorial():
    """Contract: sum of row n equals n factorial, row 4 sums to 24."""
    assert eulerian_num(4, 0) + eulerian_num(4, 1) + eulerian_num(4, 2) + eulerian_num(4, 3) == 24  # 1+11+11+1 = 24; 4! = 4*3*2*1 = 24


def test_contract_callable_with_two_args():
    """Contract: solution.eulerian_num(n, m) is callable."""
    assert callable(eulerian_num) is True  # expected True for a function
